"""
    A filename should have the following format:
    /path/to/file/filename_stem.jpg

    This function extracts filename_stem from the input filename string.

    """
def get_filename_stem(filename: Any) -> object {
    filename_stem = filename.split("/");
    filename_stem = filename_stem[-1].split(".");
    filename_stem = filename_stem[0];
    return filename_stem;
}

"""
    Performs one step in a pseudorandom sequence from state (the input argument)
    to state the return value.

    The return value is an integer, uniformly distributed in [0, pmod).

    See https://en.wikipedia.org/wiki/Linear_congruential_generator
    """
def lcg_generator(
    state: int,
    multiplier: int = 1140671485,
    addend: int = 12820163,
    pmod: int = (2 ** 24)
) -> int {
    state = ((multiplier * state) + addend) % pmod;
    return state;
}

"""
    Translates a move on a bord into a pair of indices. For example:  {'Row':A,'Column':1} ==> (0,0)
    :param move: a dict of the move.
    :return: the pair of indices.
    """
def translate_move_to_coord(move: Any) -> object {
    return ((ord(move['Row']) - 65), (move['Column'] - 1));
}

"""
		Discretize a yaw angle into the 4 canonical yaw angles/directions
	"""
def discretize_yaw(yaw: Any) -> object {
    if (yaw < 0) {
        yaw_normalized = 360 + yaw;
    } else {
        yaw_normalized = yaw;
    }
    if (
        ((yaw_normalized >= (270 + 45)) and (yaw_normalized <= 360))
        or ((yaw_normalized >= 0) and (yaw_normalized < (0 + 45)))
    ) {
        return 0;
    } elif ((yaw_normalized >= (0 + 45)) and (yaw_normalized < (90 + 45))) {
        return 90;
    } elif ((yaw_normalized >= (90 + 45)) and (yaw_normalized < (180 + 45))) {
        return 180;
    } else {
        return -90;
    }
}

