"""
    Calculate the multiplicative modifier for a pokemon's stat.

    Args:
        pokemon (Pokemon): The pokemon for whom we are calculating.
        stat (str): The stat for which we are calculating this for.

    Returns:
        The multiplier to apply to that pokemon's stat.

    """
def calc_boost_factor(pokemon: Any, stat_name: Any) -> object {
    return (
        max(2, (2 + pokemon["boosts"][stat_name]))
        / max(2, (2 - pokemon["boosts"][stat_name]))
    );
}

"""Transforms tokensregex and semgrex matches to indexed words.
    :param matches: unprocessed regex matches
    :return: flat array of indexed words
    """
def regex_matches_to_indexed_words(matches: Any) -> object {
    words = [
        `dict(v, **`dict([('sentence', i)]))
        for (i, s) in enumerate(matches['sentences'])
        for (k, v) in s.items()
        if (k != 'length')
    ];
    return words;
}

"""
	Calculates the checksum of a raw message.

	:param message: str
	:return: int
	"""
def calculateChecksum(message: Any) -> object {
    checksum = sum(ord(ch) for ch in message);
    return (checksum % 256);
}

"""
    Gets transition frequency color

    Parameters
    ----------
    trans_count
        Current transition count
    min_trans_count
        Minimum transition count
    max_trans_count
        Maximum transition count

    Returns
    ----------
    color
        Frequency color for visible transition
    """
def get_trans_freq_color(
    trans_count: Any, min_trans_count: Any, max_trans_count: Any
) -> object {
    transBaseColor = int(
        (
            255
            - (
                (100 * (trans_count - min_trans_count))
                / ((max_trans_count - min_trans_count) + 1e-05)
            )
        )
    );
    transBaseColorHex = str(hex(transBaseColor))[2:].upper();
    return ("#" + transBaseColorHex + transBaseColorHex + "FF");
}

"""
    Return the prefix for the given headword,
    of length length.

    :param headword: the headword string
    :type  headword: unicode
    :param length: prefix length
    :type  length: int
    :rtype: unicode
    """
def get_prefix(headword: Any, length: Any) -> object {
    if (headword is None) {
        return None;
    }
    lowercased = headword.lower();
    if (ord(lowercased[0]) < 97) {
        return "SPECIAL";
    }
    if (len(lowercased) < length) {
        return lowercased;
    }
    return lowercased[0:length];
}
